  .section { padding: 40px 0; }
  .accordion-item.active .accordion-body { padding: 0 16px 20px 16px; }
  .sidebar { display: none; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .header-right .search-btn { display: none; }
}

